INSERT INTO `evaluacion` (`id`, `ponderacion`, `cantidad_personas`, `contenido`, `competencias`, `instrumentos`, `fecha_evaluacion`, `id_seccion`, `corte_orden`) VALUES
(101, 25.00, 1, 'Diseño y Normalización del Esquema Relacional', 'Modelar bases de datos relacionales cumpliendo 1FN, 2FN y 3FN', 'Rúbrica analítica de modelado relacional', '2026-03-15', 501, 1),
(102, 25.00, 1, 'Consultas SQL Avanzadas y Optimización', 'Construir consultas complejas con JOINs, CTEs y vistas', 'Rúbrica de consultas y optimización SQL', '2026-04-20', 501, 1),
(103, 30.00, 2, 'Especificación de Requerimientos de Software (SRS)', 'Elaborar historias de usuario, diagramas de casos de uso y matriz de trazabilidad', 'Rúbrica de requerimientos de software', '2026-03-18', 502, 1),
(104, 35.00, 2, 'Arquitectura de Software y Prototipo Funcional', 'Diseñar arquitectura MVC/capas y construir prototipo ejecutable', 'Rúbrica de arquitectura y prototipado', '2026-05-10', 502, 1),
(105, 20.00, 1, 'Estructuras de Control y Modularización', 'Implementar funciones, estructuras selectivas y repetitivas', 'Rúbrica de algoritmos y programación', '2026-03-22', 503, 1),
(106, 30.00, 1, 'Manejo de Arreglos y Punteros', 'Manipular memoria dinámica y estructuras lineales', 'Rúbrica de algoritmos y programación', '2026-04-25', 503, 1),
(107, 25.00, 1, 'Diagnóstico del Entorno Empresarial (FODA/PESTEL)', 'Analizar variables estratégicas internas y del entorno competitivo', 'Rúbrica de diagnóstico organizacional', '2026-03-10', 504, 1),
(108, 30.00, 1, 'Estructura Organizacional y Manual de Procesos', 'Diseñar organigramas y flujogramas de procedimientos operativos', 'Rúbrica de diagnóstico organizacional', '2026-04-15', 504, 1),
(109, 30.00, 1, 'Costos por Órdenes Específicas de Producción', 'Calcular y registrar hojas de costos por órdenes', 'Rúbrica de contabilidad de costos', '2026-03-25', 505, 1),
(110, 35.00, 1, 'Análisis Costo-Volumen-Utilidad y Punto de Equilibrio', 'Determinar punto de equilibrio multiproducto y margen de seguridad', 'Rúbrica de contabilidad de costos', '2026-05-05', 505, 1),
(111, 25.00, 1, 'Análisis de Circuitos en Corriente Continua', 'Aplicar leyes de Kirchhoff y métodos de mallas/nodos', 'Rúbrica de circuitos eléctricos', '2026-03-20', 506, 1),
(112, 35.00, 2, 'Laboratorio: Teoremas de Thévenin y Norton', 'Comprobar experimentalmente circuitos equivalentes', 'Rúbrica de circuitos eléctricos', '2026-04-28', 506, 1),
(113, 30.00, 1, 'Operación y Torneado de Piezas Cilíndricas', 'Mecanizar piezas en torno paralelo cumpliendo tolerancias', 'Rúbrica de mecanizado en taller', '2026-03-28', 507, 1),
(114, 35.00, 1, 'Fresado de Superficies Planas y Ranuras', 'Operar fresadora universal y verificar acabado superficial', 'Rúbrica de mecanizado en taller', '2026-05-12', 507, 1),
(115, 30.00, 1, 'Diseño de Instrumentos de Observación Infantil', 'Diseñar listas de cotejo y escalas de estimación para infantes', 'Rúbrica de evaluación infantil', '2026-03-12', 508, 1),
(116, 35.00, 1, 'Estudio de Caso de Desarrollo Psicomotor', 'Diagnosticar e informar sobre el progreso madurativo en primera infancia', 'Rúbrica de evaluación infantil', '2026-04-22', 508, 1),
(117, 25.00, 1, 'Diseño de Interfaces Web Responsivas (CSS Grid/Flexbox)', 'Maquetar interfaces accesibles y adaptables a dispositivos móviles', 'Rúbrica de diseño UI/UX', '2025-09-25', 509, 2),
(118, 35.00, 1, 'Desarrollo de SPA con Consumo de API REST', 'Construir aplicaciones frontend interactivas con validación de formularios', 'Rúbrica de diseño UI/UX', '2025-11-15', 509, 3),
(119, 25.00, 1, 'Planificación de Capacidad y Distribución de Planta', 'Calcular carga de trabajo y optimizar rutas de producción', 'Rúbrica de gestión de operaciones', '2025-09-20', 510, 2),
(120, 30.00, 1, 'Control Estadístico de Procesos y Gestión de Inventarios', 'Elaborar gráficos de control X-R y modelos de lote económico', 'Rúbrica de gestión de operaciones', '2025-11-18', 510, 3);
