(105, 'Rúbrica de Algoritmos y Programación Modular', '12345689', 'Evalúa la lógica algorítmica, descomposición modular en funciones, manejo de datos y legibilidad del código.', 1, NOW(), NOW(), 1),
(106, 'Rúbrica de Diagnóstico Organizacional Estratégico', '12345679', 'Evalúa la profundidad del análisis de factores internos y externos, formulación de objetivos y viabilidad.', 1, NOW(), NOW(), 1),
