(111, 'Rúbrica de Diseño UI/UX y Desarrollo Web', '12345689', 'Evalúa la estructura semántica HTML5, responsividad CSS, accesibilidad visual y consumo asíncrono de APIs.', 1, NOW(), NOW(), 1),
(112, 'Rúbrica de Gestión de Operaciones y Planta', '31466704', 'Evalúa el balanceo de líneas productivas, cálculo de tiempos estándar, distribución física y control estadístico.', 1, NOW(), NOW(), 1);
